<script setup lang="ts">
const route=useRoute();const token=String(route.params.token)
const {data,error}=await useFetch<{data:{email:string;role:string;workspace:{name:string}}}>(`/api/invitations/${token}`)
const password=ref('');const busy=ref(false);const message=ref('')
const accept=async()=>{busy.value=true;message.value='';try{await $fetch('/api/invitations/accept',{method:'POST',body:{token,...(password.value?{password:password.value}:{})}});await navigateTo('/library')}catch(err:unknown){const failure=err as {statusCode?:number;data?:{message?:string}};if(failure.statusCode===401){await navigateTo(`/login?redirect=${encodeURIComponent(route.fullPath)}`);return}message.value=failure.data?.message??'Unable to accept this invitation.'}finally{busy.value=false}}
</script>
<template><main class="page-shell"><section class="message-panel"><p class="eyebrow">Workspace invitation</p><template v-if="data"><h1>Join {{ data.data.workspace.name }}.</h1><p class="muted">You were invited as {{ data.data.role }} using {{ data.data.email }}.</p><form @submit.prevent="accept"><label for="invite-password">Password for a new account</label><input id="invite-password" v-model="password" type="password" minlength="12" autocomplete="new-password" placeholder="Leave empty if you already have an account"><small>Existing users will be asked to sign in. New users must choose at least 12 characters.</small><button type="submit" :disabled="busy">{{busy?'Joining…':'Join workspace'}}</button></form><p v-if="message" class="form-error" role="alert">{{message}}</p></template><template v-else><h1>Invitation unavailable.</h1><p class="muted">{{error?'This invitation is invalid or has expired.':'Loading invitation…'}}</p></template></section></main></template>
